mapper.sql:
SELECT 'DR' AS RECORD_TYPE , A.MDFM_CLS_CD RECORD_DETAIL_TYPE , NULL AS ITEM_TYPE /* D007, D020 관련 특수 조건 관련 해결 필요 */ , NULL AS ITEM_NM /*, NVL(B.OP_DTM, A.MDF_REC_DTM) AS WRITING_DATE*/ , A.MDF_REC_DTM AS WRITING_DATE , A.WRTR_DEPT_CD AS WRITING_DEPT_CD , NULL AS WRITING_DEPT_NM , A.WK_STF_NO AS WRITER_STF_NO , NULL AS WRITER_NM , NULL AS KEY_ID , A.PACT_ID AS PACT_ID , A.PACT_TP_CD AS PACT_TP_CD , ROW_NUMBER() OVER (PARTITION BY TO_CHAR(A.MDF_REC_DTM, 'YYYY-MM-DD') ORDER BY A.REC_DTM DESC) AS SORT_SEQ , NULL AS NOTE , A.MDRC_FOM_SEQ AS PRINT_SEQ , A.MDRC_ID , A.MDFM_ID , NULL AS EXAM_KEY , NULL AS PACS_IMG_IPTN_CD , NULL AS ACCS_ID , NULL AS RECTYPE , NULL AS GENE_EXM_YN , CASE WHEN A.MDRC_WRT_STS_CD > 10 THEN 'Y' END MDRC_WRT_STS_CD_YN , A.MDRC_FOM_SEQ , NULL AS OP_EXPT_REG_ID , A.MDFM_CLS_DTL_CD AS COMN_CD FROM ODS.S_MRDDRECM A LEFT OUTER JOIN ODS.S_MRDDRONE B ON A.MDRC_ID = B.MDRC_ID AND A.MDRC_FOM_SEQ = B.MDRC_FOM_SEQ WHERE A.PT_NO = #{ptNo} AND A.MDFM_CLS_CD = 'D005' AND A.PACT_TP_CD = DECODE(#{pactTpCd}, 'ALL', A.PACT_TP_CD, #{pactTpCd})
AND A.PT_MED_DEPT_CD = #{deptCd} AND A.WRTR_DEPT_CD = #{deptCd} AND A.WK_SID = #{writerStfNo} AND A.WK_STF_NO = #{writerStfNo}
AND A.LST_YN = 'Y' AND A.MDRC_DC_TP_CD = 'C' AND B.OPRC_ELMT_CLS_CD = '17' AND ((B.OP_DTM::DATE IS NOT NULL AND B.OP_DTM::DATE BETWEEN #{searchFromDate}::DATE AND #{searchToDate}::DATE) OR (B.OP_DTM::DATE IS NULL AND A.MDF_REC_DTM::DATE BETWEEN #{searchFromDate}::DATE AND #{searchToDate}::DATE)) AND NOT EXISTS(SELECT 1 FROM ODS.S_MRFMFORM WHERE MDFM_ID = A.MDFM_ID AND MDFM_FOM_SEQ = A.MDFM_FOM_SEQ AND MDFM_CLS_CD = 'D020' AND MDFM_APY_CTRA_CD = 4) AND NOT EXISTS(SELECT 'Y' FROM ODS.S_CNLRRUSD W WHERE W.STF_NO = A.WRT_STF_NO AND W.OCTY_TP_CD IN ('Z06') )

SELECT 'DR' AS RECORD_TYPE , A.MDFM_CLS_CD AS RECORD_DETAIL_TYPE , NULL AS ITEM_TYPE /* D007, D020 관련 특수 조건 관련 해결 필요 */ , NULL AS ITEM_NM , NVL(B.DS_DT, A.MDF_REC_DTM) AS WRITING_DATE , A.WRTR_DEPT_CD AS WRITING_DEPT_CD , NULL AS WRITING_DEPT_NM , A.WK_STF_NO AS WRITER_STF_NO , NULL AS WRITER_NM , NULL AS KEY_ID , A.PACT_ID AS PACT_ID , A.PACT_TP_CD AS PACT_TP_CD , ROW_NUMBER() OVER (PARTITION BY TO_CHAR(A.MDF_REC_DTM, 'YYYY-MM-DD') ORDER BY A.REC_DTM DESC) AS SORT_SEQ , NULL AS NOTE , A.MDRC_FOM_SEQ AS PRINT_SEQ , A.MDRC_ID , A.MDFM_ID , NULL AS EXAM_KEY , NULL AS PACS_IMG_IPTN_CD , NULL AS ACCS_ID , NULL AS RECTYPE , NULL AS GENE_EXM_YN , CASE WHEN A.MDRC_WRT_STS_CD > 10 THEN 'Y' END MDRC_WRT_STS_CD_YN , A.MDRC_FOM_SEQ , NULL AS OP_EXPT_REG_ID , A.MDFM_CLS_DTL_CD AS COMN_CD FROM ODS.S_MRDDRECM A LEFT OUTER JOIN (SELECT Q.PT_NO AS PT_NO , Q.PACT_ID AS PACT_ID , Q.DS_DTM AS DS_DT FROM ODS.S_ACPPRAAM Q WHERE Q.PT_NO = #{ptNo} UNION ALL SELECT Q.PT_NO AS PT_NO , Q.PACT_ID AS PACT_ID , Q.CHOT_DTM AS DS_DT FROM ODS.S_ACPPRETM Q WHERE Q.PT_NO = #{ptNo} ) B ON A.PT_NO = B.PT_NO AND A.PACT_ID = B.PACT_ID WHERE A.PT_NO = #{ptNo} AND A.MDFM_CLS_CD = 'D006' /* 퇴원기록 */ AND A.PACT_TP_CD = DECODE(#{pactTpCd}, 'ALL', A.PACT_TP_CD, #{pactTpCd})
AND A.PT_MED_DEPT_CD = #{deptCd} AND A.WRTR_DEPT_CD = #{deptCd} AND A.WK_SID = #{writerStfNo} AND A.WK_STF_NO = #{writerStfNo}
AND A.LST_YN = 'Y' AND A.MDRC_DC_TP_CD = 'C' AND ((B.DS_DT::DATE IS NOT NULL AND B.DS_DT::DATE BETWEEN #{searchFromDate}::DATE AND #{searchToDate}::DATE AND A.PT_NO = B.PT_NO AND A.PACT_ID = B.PACT_ID) OR (B.DS_DT::DATE IS NULL AND A.MDF_REC_DTM::DATE BETWEEN #{searchFromDate}::DATE AND #{searchToDate}::DATE)) AND NOT EXISTS(SELECT 1 FROM ODS.S_MRFMFORM WHERE MDFM_ID = A.MDFM_ID AND MDFM_FOM_SEQ = A.MDFM_FOM_SEQ AND MDFM_CLS_CD = 'D020' AND MDFM_APY_CTRA_CD = 4) AND NOT EXISTS(SELECT 'Y' FROM ODS.S_CNLRRUSD W WHERE W.STF_NO = A.WRT_STF_NO AND W.OCTY_TP_CD IN ('Z06') )
